input.command:
cd ~/hermes_extract && python3 << 'EOF'
import struct

# Simple binary Manifest parser
manifest = open('AndroidManifest.xml', 'rb').read()

# Search for strings that look like permissions
strings_found = []
i = 0
while i < len(manifest):
    if manifest[i:i+8] == b'android':
        # Extract null-terminated string
        end = manifest.find(b'\x00', i)
        if end > i and end < i + 200:
            try:
                s = manifest[i:end].decode('utf-8', errors='ignore')
                if len(s) > 3 and '.' in s:
                    strings_found.append(s)
            except:
                pass
    i += 1

# Print unique strings
for s in sorted(set(strings_found))[:100]:
    print(s)
EOF

